        add(WildRiftItem("guinsoo_s_rageblade_physical", "Espadafuria de Guinsoo", ItemCategory.PHYSICAL, 3100, "+30% Velocidad de Ataque", "Applies on-hit effects AS +30% Attack SpeedSurge: Gain 5% Velocidad de Movimiento.Chaos: Gain 25 Daño de Ataque or 50 Poder de Habilidad (Adaptive).Wrath: Attacks deal 30 Daño Mágico but no longer Critical Strike. Fore every 1% Critical Strike Rate gained from items, your Daño Mágico Aumenta by 1.5, up to a max increase of 75 (reached at 50% Probabilidad de Crítico).Seething Strike: Attacks grant 8% Velocidad de Ataque, staking up to 4 times for a maximum of 32% Velocidad de Ataque). While fully stacked, every 3 attacks applies on-hit effects an additional 1 times.", "https://wr-meta.com/uploads/posts/2026-01/1768000022_abb24fd724faa77b82baf985dea956b8eae9f31a-512x512.webp"))
        add(WildRiftItem("kraken_slayer_physical", "Verdugo de Krakens", ItemCategory.PHYSICAL, 2800, "+40 Daño de Ataque, +30% Velocidad de Ataque", "Deal bonus Daño Físico AD +40 Daño de Ataque AS +30% Attack SpeedCloud Stride: MS +5% Velocidad de Movimiento.Bring it Down: Every third attack Inflige 120-160 () bonus Daño Físico (110-150 () for ranged champions), increased by 1% per 1% Vida the target is missing, up to an increase of 70%.", "https://wr-meta.com/uploads/posts/2026-03/1772630263_kraken-slayer.webp"))
        add(WildRiftItem("overlord_s_bloodmail_physical", "Armadura Sangrienta del Señor Supremo", ItemCategory.PHYSICAL, 3200, "+450 Vida Máxima, +30 Daño de Ataque", "Gain Daño de Ataque when losing Vida HP +450 Vida Máxima AD +30 Attack DamageTyranny: Gain Daño de Ataque equal to 2.5% of your bonus Vida.Retribution: Gain up to 9% increased Daño de Ataque based on your missing Vida. Maximum Retribution bonus while below 30% Vida.", "https://wr-meta.com/uploads/posts/2026-03/1772630274_overlords-bloodmail.webp"))
        add(WildRiftItem("experimental_hexplate_physical", "Hexoplaca Experimental", ItemCategory.PHYSICAL, 3000, "+400 Vida Máxima, +35 Daño de Ataque, +20% Velocidad de Ataque", "Gain Velocidad de Ataque & Velocidad de Movimiento when your ultimate is cast HP +400 Vida Máxima AD +35 Daño de Ataque AS +20% Attack SpeedHexcharged: Gain +20 Aceleración de Habilidad for your ultimate ability.Overdrive: After using your ultimate ability, gain 40% Velocidad de Ataque (20% for ranged champions) and 20% Velocidad de Movimiento (10% for ranged champions) for 8s. (30s Enfriamiento)", "https://wr-meta.com/uploads/posts/2026-03/1772630328_experimental-hexplate.webp"))
        add(WildRiftItem("dominik_s_regards_physical", "Recuerdos de Lord Dominik", ItemCategory.PHYSICAL, 3300, "+30 Daño de Ataque, +36% Penetración de Armadura, +25% Probabilidad de Crítico", "Already equipped with percentage Penetración de Armadura and bonus damage, but lacks durability AD +30 Daño de Ataque +36% Penetración de Armadura Crit Chance +25% Critical RateGiant Slayer: Deal bonus damage based on the target’s bonus Vida. At 1500 bonus Vida, the bonus damage is increased up to 15%. 3300 Dominik’s Regards TIPS: Is built to punish bulky foes. It converts a chunk of your offensive power into Penetración de Armadura and adds bonus damage that scales with the enemy’s extra Vida, making it a go-to pick when the enemy team stacks HP and Armadura. Because it focuses on penetration and damage rather than survivability, use it when you need to cut through tanky targets quickly while relying on positioning or teammates for protection.", "https://wr-meta.com/uploads/posts/2026-03/1774953440_lord-dominiks-regards.webp"))
