        add(WildRiftItem("randuin_s_omen_defense", "Presagio de Randuin", ItemCategory.DEFENSE, 2800, "+400 Vida Máxima, +75 Armadura", "Counters Critical Strike Damage HP +400 Vida Máxima Armadura +75 ArmorResilience: Critically Struck deal 30% less damage to you.Countercurrent: Gain 1 stacks of Countercurrent when Critically Struck by Daño Físico. Each stuck Otorga 5% Velocidad de Movimiento and 5% slow resist. Max 4 stacks.", "https://wr-meta.com/uploads/posts/2025-07/1753389031_randuins-omen.webp"))
