        add(WildRiftItem("dawnshroud_support", "Manto del Amanecer", ItemCategory.SUPPORT, 2700, "+250 Vida Máxima, +50 Armadura, +30 Resistencia Mágica", "Immobilize effects damage and reveal around you HP +250 Vida Máxima Armadura +50 Armadura +30 Magic ResistanceDawnbringer: When you immobilize a champion champion or are immobilized within 400 units of an enemy champion, reveal all nearby enemy champions for 3 seconds, deal Daño Mágico equal to 40 + 2.5% bonus HP and gain 20% Armadura Armadura and Resistencia Mágica (3s Enfriamiento)", "https://wr-meta.com/uploads/posts/2025-07/1753389211_dawnshroud.webp"))
